/**
 * Lab-only actual Three.js scene. The actor, sack, pallet and motor position
 * tracks are generated by the planner compiler; no Gemini call or preset.
 */
import * as THREE from 'three';
import {SceneProgram3D} from '../../src/studio/explainer/sceneProgram/stage3d';
import {compileSceneProgram} from '../../src/studio/explainer/sceneProgram/score';
import {sampleCompiledFilm,sampleSources} from '../../src/studio/explainer/sceneProgram/planner/sample';

const WIDTH=720,HEIGHT=1280;
const canvas=document.querySelector<HTMLCanvasElement>('#scene')!;
const webgl=new THREE.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});
webgl.setPixelRatio(1);webgl.setSize(WIDTH,HEIGHT,false);
webgl.shadowMap.enabled=true;webgl.shadowMap.type=THREE.PCFSoftShadowMap;
webgl.outputColorSpace=THREE.SRGBColorSpace;

const {program,storyboard,diagnostics}=sampleCompiledFilm();
const score=compileSceneProgram(program,sampleSources);
const stage=new SceneProgram3D(program,sampleSources);
const composite=document.createElement('canvas');composite.width=WIDTH;composite.height=HEIGHT;
const ctx=composite.getContext('2d')!;
function caption(t:number) {
  if(t<1.1)return 'O trabalhador pega o mesmo saco.';
  if(t<4)return 'Ele transporta a carga até a plataforma.';
  if(t<5.1)return 'O saco fica apoiado no elevador.';
  if(t<6.5)return 'O motor é ligado.';
  if(t<12.3)return 'O motor levanta a plataforma e o saco juntos.';
  return 'A mesma carga chega ao andar superior.';
}
function wrap(text:string,maxWidth:number):string[]{
  const words=text.split(' '),rows:string[]=[];let current='';
  for(const word of words){
    const proposal=current?current+' '+word:word;
    if(ctx.measureText(proposal).width>maxWidth&&current){rows.push(current);current=word;}
    else current=proposal;
  }
  if(current)rows.push(current);
  return rows;
}
const seek=(t:number)=>{
  stage.render(webgl,t,WIDTH,HEIGHT);
  ctx.clearRect(0,0,WIDTH,HEIGHT);
  ctx.drawImage(canvas,0,0,WIDTH,HEIGHT);
  const panelHeight=168;
  ctx.fillStyle='rgba(12,23,35,0.89)';ctx.fillRect(0,HEIGHT-panelHeight,WIDTH,panelHeight);
  ctx.fillStyle='#6fd7f0';ctx.fillRect(38,HEIGHT-panelHeight+23,64,6);
  ctx.font='bold 30px sans-serif';ctx.fillStyle='white';
  const rows=wrap(caption(t),WIDTH-76);
  rows.forEach((line,i)=>ctx.fillText(line,38,HEIGHT-panelHeight+74+i*39));
  const active=storyboard.events.filter(e=>t>=e.start&&t<e.end).map(e=>e.id);
  const positions=Object.fromEntries(['trabalhador','saco','elevador','motor'].map(id=>
    [id,stage.nodes.get(id)?.position.toArray()]));
  return {
    time:t,active,positions,
    gear:stage.nodes.get('drive-gear')?.rotation.toArray(),
    camera:stage.camera.position.toArray(),
    bounds:stage.diagnostics().projectedBounds
  };
};
(window as any).__storyEvents3D={
  seek,
  frame:()=>composite.toDataURL('image/png'),
  info:{
    source:'Offline deterministic event compiler, NOT Gemini-generated video',
    duration:score.duration,objects:program.nodes.length,
    tracks:program.tracks.length,events:storyboard.events.length,
    captions:'Authored directly from provided sampleSource phrases; no invented narration',
    warnings:storyboard.warnings,diagnostics
  }
};
seek(0);
document.body.dataset.ready='story-event-3d';